// relation: shortClassName_class_string_overload_agree
// holds because: The Class and String overloads of getShortClassName are documented to compute the class name minus the package name from equivalent representations of the same type; for a non-null Class cls, passing cls and passing cls.getName() denote the same class.
// valid input: Choose a valid Class<?> from a small set that exercises ordinary classes, inner classes, primitive arrays, and object arrays: String.class, String[].class, int[].class, or java.util.Map.Entry[].class.
Class<?> cls;
int choice = data.consumeInt(0, 3);
if (choice == 0) {
  cls = String.class;
} else if (choice == 1) {
  cls = String[].class;
} else if (choice == 2) {
  cls = int[].class;
} else {
  cls = java.util.Map.Entry[].class;
}
String a;
String b;
try { a = org.apache.commons.lang.ClassUtils.getShortClassName(cls); b = org.apache.commons.lang.ClassUtils.getShortClassName(cls.getName()); } catch (Exception e) { return; }
if (!a.equals(b)) throw new RuntimeException("relation shortClassName_class_string_overload_agree violated: " + a + " vs " + b + " for " + cls);

