// relation: minus_positive_integer_has_no_forced_space
// holds because: Compact printing should not add unnecessary spaces; the special separator exists only to avoid the specific token collision '--' created by a negative literal after '-'. A positive integer after '-' therefore remains compact.
// valid input: Use a simple positive integer literal after '-'. Choose a small positive digit from fuzz data and print the expression "x-<n>".
int n = data.consumeInt(1, 9);
String js = "x-" + n;
String out;
try {
  Compiler c = new Compiler();
  com.google.javascript.rhino.Node root = c.parseTestCode(js);
  out = new CodePrinter.Builder(root)
      .setPrettyPrint(false)
      .setLineLengthThreshold(CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)
      .build();
} catch (Exception e) { return; }
String expected = "x-" + n;
if (!expected.equals(out)) {
  throw new RuntimeException("relation minus_positive_integer_has_no_forced_space violated: " + out + " vs " + expected);
}

