package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    private static final double EPS = 1.0e-8;

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        data.consumeRemainingAsBytes();

        JennrichSampsonModel function = new JennrichSampsonModel(
                10,
                new double[] { 0.3, 0.4 });

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (function.getN() + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final org.apache.commons.math.optimization.VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(
                    function,
                    function.getTarget(),
                    function.getWeight(),
                    function.getStartPoint());
        } catch (org.apache.commons.math.FunctionEvaluationException e) {
            return;
        } catch (org.apache.commons.math.optimization.OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        double[] point = optimum.getPointRef();
        if (point == null || point.length != 2) {
            return;
        }

        assertClose("jennrich-seed-param0", point[0], 0.2578330049, EPS);
        assertClose("jennrich-seed-param1", point[1], 0.257829976764542, EPS);
        assertClose("jennrich-seed-rms", optimizer.getRMS(), 11.1517793413499, EPS);

        // Contract basis:
        // getChiSquare() reports the chi-square value, while updateResidualsAndCost()
        // computes it from targetValues, residualsWeights, and the current objective.
        // Therefore the reported chi-square must agree with a fresh recomputation from
        // the returned point using the real function and the same target/weights.
        final double[] freshObjective;
        try {
            freshObjective = function.value(point);
        } catch (org.apache.commons.math.FunctionEvaluationException e) {
            return;
        } catch (RuntimeException e) {
            return;
        }

        double[] target = function.getTarget();
        double[] weight = function.getWeight();
        if (freshObjective.length != target.length || target.length != weight.length) {
            return;
        }

        double recomputedChiSquare = 0.0;
        for (int i = 0; i < freshObjective.length; i++) {
            double residual = target[i] - freshObjective[i];
            recomputedChiSquare += weight[i] * residual * residual;
        }

        double reportedChiSquare = optimizer.getChiSquare();
        double tol = Math.max(1.0e-9, Math.abs(recomputedChiSquare) * 1.0e-12);
        if (Math.abs(reportedChiSquare - recomputedChiSquare) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-chisquare-recompute] consistency violation: reported="
                            + reportedChiSquare
                            + " recomputed="
                            + recomputedChiSquare);
        }
    }

    private static void assertClose(String oracleId, double actual, double expected, double tol) {
        if (Double.isNaN(actual) || Double.isInfinite(actual) || Math.abs(actual - expected) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + oracleId + "] semantic mismatch: expected=" + expected + " actual=" + actual);
        }
    }

    private static final class JennrichSampsonModel
            implements org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction {
        private final int m;
        private final double[] startPoint;
        private final double[] target;
        private final double[] weight;

        private JennrichSampsonModel(int m, double[] startPoint) {
            this.m = m;
            this.startPoint = startPoint.clone();
            this.target = new double[m];
            this.weight = new double[m];
            for (int i = 0; i < m; i++) {
                target[i] = 0.0;
                weight[i] = 1.0;
            }
        }

        int getN() {
            return startPoint.length;
        }

        double[] getStartPoint() {
            return startPoint.clone();
        }

        double[] getTarget() {
            return target.clone();
        }

        double[] getWeight() {
            return weight.clone();
        }

        public double[] value(double[] point) throws org.apache.commons.math.FunctionEvaluationException {
            if (point == null || point.length != 2) {
                throw new org.apache.commons.math.FunctionEvaluationException(point);
            }
            double[] values = new double[m];
            for (int i = 0; i < m; i++) {
                double idx = i + 1.0;
                values[i] = 2.0 + 2.0 * idx - Math.exp(idx * point[0]) - Math.exp(idx * point[1]);
            }
            return values;
        }

        public org.apache.commons.math.analysis.MultivariateMatrixFunction jacobian() {
            return new org.apache.commons.math.analysis.MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws IllegalArgumentException {
                    if (point == null || point.length != 2) {
                        throw new IllegalArgumentException();
                    }
                    double[][] jac = new double[m][2];
                    for (int i = 0; i < m; i++) {
                        double idx = i + 1.0;
                        jac[i][0] = -idx * Math.exp(idx * point[0]);
                        jac[i][1] = -idx * Math.exp(idx * point[1]);
                    }
                    return jac;
                }
            };
        }
    }
}

package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double[] EXPECTED_MIN_PARAMS = {
        0.2578330049, 0.257829976764542
    };
    private static final double EXPECTED_MIN_RMS = 11.1517793413499;
    private static final double PARAM_TOL = 1.0e-6;
    private static final double RMS_TOL = 1.0e-6;
    private static final double REL_TOL = 1.0e-10;

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Object function = instantiateJennrichSampson();
        if (function == null) {
            return;
        }

        try {
            runSeedOracle(function);
            runChiSquareRmsConsistency(function, data.consumeBoolean());
            runExploration(function, data);
        } catch (FuzzerSecurityIssueLow e) {
            throw e;
        } catch (Throwable t) {
            // Rejections are not semantic violations.
        }
    }

    private static void runSeedOracle(Object function)
            throws FunctionEvaluationException, OptimizationException {
        LevenbergMarquardtOptimizer optimizer = configuredOptimizer(function);
        VectorialPointValuePair optimum = optimizer.optimize(
                (DifferentiableMultivariateVectorialFunction) function,
                invokeDoubleArray(function, "getTarget"),
                invokeDoubleArray(function, "getWeight"),
                invokeDoubleArray(function, "getStartPoint"));

        double[] point = optimum.getPointRef();
        if (point.length != EXPECTED_MIN_PARAMS.length) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-seed-shape] semantic mismatch: expected point length "
                            + EXPECTED_MIN_PARAMS.length + " but was " + point.length);
        }

        if (!close(point[0], EXPECTED_MIN_PARAMS[0], PARAM_TOL, REL_TOL)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-seed-param0] semantic mismatch: expected "
                            + EXPECTED_MIN_PARAMS[0] + " but was " + point[0]);
        }

        if (!close(point[1], EXPECTED_MIN_PARAMS[1], PARAM_TOL, REL_TOL)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-seed-param1] semantic mismatch: expected "
                            + EXPECTED_MIN_PARAMS[1] + " but was " + point[1]);
        }

        double rms = optimizer.getRMS();
        if (!close(rms, EXPECTED_MIN_RMS, RMS_TOL, REL_TOL)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-seed-rms] semantic mismatch: expected "
                            + EXPECTED_MIN_RMS + " but was " + rms);
        }
    }

    private static void runChiSquareRmsConsistency(Object function, boolean alsoCallCovariances)
            throws FunctionEvaluationException, OptimizationException {
        LevenbergMarquardtOptimizer optimizer = configuredOptimizer(function);
        optimizer.optimize(
                (DifferentiableMultivariateVectorialFunction) function,
                invokeDoubleArray(function, "getTarget"),
                invokeDoubleArray(function, "getWeight"),
                invokeDoubleArray(function, "getStartPoint"));

        if (alsoCallCovariances) {
            try {
                optimizer.getCovariances();
            } catch (Throwable t) {
                return;
            }
        }

        double rms = optimizer.getRMS();
        double chiSquare = optimizer.getChiSquare();
        double expectedChiSquare = rms * rms * optimizer.rows;
        // AbstractLeastSquaresOptimizer javadoc: RMS is sqrt(c/n), where c is the criterion.
        // getChiSquare reports that criterion, so for every correct implementation:
        // chiSquare == rows * RMS^2. A band-aid that returns early with stale residual/cost state
        // can leave these summaries disagreeing even if no exception is thrown.
        if (!close(chiSquare, expectedChiSquare, 1.0e-8, 1.0e-10)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-rms-chisquare-formula] consistency violation: chiSquare="
                            + chiSquare + " expectedFromRMS=" + expectedChiSquare
                            + " rows=" + optimizer.rows + " rms=" + rms);
        }
    }

    private static void runExploration(Object function, FuzzedDataProvider data) {
        try {
            double[] start = invokeDoubleArray(function, "getStartPoint").clone();
            if (start.length == 0) {
                return;
            }
            int idx = data.consumeInt(0, start.length - 1);
            double delta = data.consumeInt(-1000, 1000) / 1000.0;
            start[idx] += delta;

            LevenbergMarquardtOptimizer optimizer = configuredOptimizer(function);
            optimizer.optimize(
                    (DifferentiableMultivariateVectorialFunction) function,
                    invokeDoubleArray(function, "getTarget"),
                    invokeDoubleArray(function, "getWeight"),
                    start);

            if (data.consumeBoolean()) {
                optimizer.getChiSquare();
            }
            if (data.consumeBoolean()) {
                optimizer.getRMS();
            }
            if (data.consumeBoolean()) {
                try {
                    optimizer.getCovariances();
                } catch (Throwable t) {
                    return;
                }
            }
        } catch (Throwable t) {
            // Explore only; no oracle for arbitrary starts.
        }
    }

    private static LevenbergMarquardtOptimizer configuredOptimizer(Object function) {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        int n = invokeInt(function, "getN");
        optimizer.setMaxIterations(100 * (n + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);
        return optimizer;
    }

    private static Object instantiateJennrichSampson() {
        String[] candidates = {
            "org.apache.commons.math.optimization.general.JennrichSampsonFunction",
            "org.apache.commons.math.optimization.general.MinpackTest$JennrichSampsonFunction"
        };
        for (String name : candidates) {
            try {
                Class<?> cls = Class.forName(name);
                Object outer = null;
                if (cls.getEnclosingClass() != null && !Modifier.isStatic(cls.getModifiers())) {
                    outer = cls.getEnclosingClass().getDeclaredConstructor().newInstance();
                }
                for (Constructor<?> c : cls.getDeclaredConstructors()) {
                    c.setAccessible(true);
                    Class<?>[] p = c.getParameterTypes();
                    if (outer == null && p.length == 5) {
                        return c.newInstance(
                                Integer.valueOf(10),
                                new double[] {0.3, 0.4},
                                Double.valueOf(64.5856498144943),
                                Double.valueOf(11.1517793413499),
                                new double[] {0.2578330049, 0.257829976764542});
                    }
                    if (outer != null && p.length == 6 && p[0].isInstance(outer)) {
                        return c.newInstance(
                                outer,
                                Integer.valueOf(10),
                                new double[] {0.3, 0.4},
                                Double.valueOf(64.5856498144943),
                                Double.valueOf(11.1517793413499),
                                new double[] {0.2578330049, 0.257829976764542});
                    }
                }
            } catch (Throwable t) {
                // Try next candidate.
            }
        }
        return null;
    }

    private static double[] invokeDoubleArray(Object target, String name) {
        try {
            Method m = target.getClass().getMethod(name);
            m.setAccessible(true);
            return (double[]) m.invoke(target);
        } catch (Throwable t) {
            throw new RuntimeException(t);
        }
    }

    private static int invokeInt(Object target, String name) {
        try {
            Method m = target.getClass().getMethod(name);
            m.setAccessible(true);
            return ((Integer) m.invoke(target)).intValue();
        } catch (Throwable t) {
            throw new RuntimeException(t);
        }
    }

    private static boolean close(double a, double b, double absTol, double relTol) {
        if (Double.doubleToLongBits(a) == Double.doubleToLongBits(b)) {
            return true;
        }
        double diff = Math.abs(a - b);
        double scale = Math.max(Math.abs(a), Math.abs(b));
        return diff <= absTol || diff <= relTol * scale;
    }
}

