package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.analysis.SinFunction;
import org.apache.commons.math.analysis.UnivariateRealFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        UnivariateRealFunction sin = new SinFunction();

        try {
            new BrentSolver().solve(sin, 1.0, 1.5, 1.2);
        } catch (Throwable ignored) {
        }

        int multiple = data.consumeInt(1, 4);
        double min = multiple * Math.PI;
        double max = min + (Math.PI / 2.0);
        double initial = min + (Math.PI / 4.0);

        BrentSolver solver = new BrentSolver();
        double actual;
        try {
            actual = solver.solve(sin, min, max, initial);
        } catch (Throwable ignored) {
            return;
        }

        double reported = solver.getResult();
        int iterations = solver.getIterationCount();

        if (actual < min || actual > max) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:endpoint-root-in-interval] consistency violation: returned root must lie in the interval it solves over; " +
                "min=" + min + " max=" + max + " initial=" + initial + " actual=" + actual);
        }

        if (reported < min || reported > max) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:reported-endpoint-root-in-interval] consistency violation: stored result must lie in the interval it solves over; " +
                "min=" + min + " max=" + max + " initial=" + initial + " reported=" + reported);
        }

        // Contract justification: this input is constructed from a known answer.
        // For SinFunction, sin(k*pi) is zero; with min = k*pi and min < initial < max,
        // the endpoint min is an exact known root, so a correct solver must return min.
        if (Math.abs(actual - min) > 1.0e-12) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:min-endpoint-known-root] semantic mismatch: expected exact endpoint root at min; " +
                "expected=" + min + " actual=" + actual + " reported=" + reported);
        }

        // Contract justification: the method body returns immediately via setResult(..., 0)
        // when an endpoint is good enough, so a correct implementation reports zero iterations.
        // A band-aid that only changes throwing behavior would not repair this helper/state coupling.
        if (iterations != 0) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:min-endpoint-zero-iterations] consistency violation: exact endpoint root should be accepted with zero iterations; " +
                "min=" + min + " actual=" + actual + " iterations=" + iterations);
        }
    }
}

