double t2 = (double) data.consumeInt(-50, 50);
double w1 = (double) data.consumeInt(1, 20);
double w2 = (double) data.consumeInt(1, 20);
double s = (double) data.consumeInt(-50, 50);
org.apache.commons.math.optimization.general.LevenbergMarquardtOptimizer opt = new org.apache.commons.math.optimization.general.LevenbergMarquardtOptimizer();
org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction f = new org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction() {
    public double[] value(double[] p) {
        return new double[] { p[0], p[0] };
    }
    public org.apache.commons.math.analysis.MultivariateMatrixFunction jacobian() {
        return new org.apache.commons.math.analysis.MultivariateMatrixFunction() {
            public double[][] value(double[] p) {
                return new double[][] { { 1.0 }, { 1.0 } };
            }
        };
    }
};
org.apache.commons.math.optimization.VectorialPointValuePair r;
double chi;
try {
    r = opt.optimize(f, new double[] { t1, t2 }, new double[] { w1, w2 }, new double[] { s });
    chi = opt.getChiSquare();
} catch (Exception e) { return; }
double x = r.getPointRef()[0];
double expected = w1 * (t1 - x) * (t1 - x) + w2 * (t2 - x) * (t2 - x);
double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expected)));
if (!(Math.abs(chi - expected) <= tol)) throw new RuntimeException("relation chiSquare_matches_weighted_residual_sum violated: " + chi + " vs " + expected);

