                            + n + " result=" + boundaryResult);
        }

        double shift = data.consumeInt(-1000, 1000);
        double[] xs = new double[n];
        double[] ys = new double[n];
        for (int i = 0; i < n; i++) {
            xs[i] = x[i] + shift;
            ys[i] = y[i] + shift;
