package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static final class WarningSummary {
        final int count;
        final String[] descriptions;

        WarningSummary(int count, String[] descriptions) {
            this.count = count;
            this.descriptions = descriptions;
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String expectedWarning =
                "assignment\n" +
                "found   : null\n" +
                "required: boolean";

        // Lifted directly from LooseTypeCheckTest.testFunctionArguments13.
        // This program has a JSDoc-declared boolean parameter. The patched code changes
        // declareArguments() so that such parameters are defined as non-inferred. On the buggy
        // build they are incorrectly marked inferred, so assigning null does not produce the
        // expected type warning.
        String seedJs =
                "/** @return {boolean} */ function u() { return true; }" +
                "/** @param {boolean} b\n@return {?boolean} */" +
                "function f(b) { if (u()) { b = null; } return b; }";

        WarningSummary seed = runTypeCheck(seedJs);
        String expectedNorm = normalize(expectedWarning);
        if (!containsNormalized(seed, expectedNorm)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:testFunctionArguments13] semantic mismatch: expected warning="
                            + expectedNorm + " actualCount=" + seed.count
                            + " warnings=" + join(seed.descriptions));
        }

        // Equivalent-input generalization: renaming identifiers preserves the typing semantics.
        // The warning text itself is still fixed because it mentions only the found/required types.
        String uName = sanitizeIdentifier(data.consumeAsciiString(8), "u");
        String fName = sanitizeIdentifier(data.consumeAsciiString(8), "f");
        String pName = sanitizeIdentifier(data.consumeAsciiString(8), "b");
        if (uName.equals(fName)) {
            fName = fName + "x";
        }
        if (pName.equals(uName) || pName.equals(fName)) {
            pName = pName + "y";
        }

        String renamedJs =
                "/** @return {boolean} */ function " + uName + "() { return true; }" +
                "/** @param {boolean} " + pName + "\n@return {?boolean} */" +
                "function " + fName + "(" + pName + ") { if (" + uName + "()) { " + pName +
                " = null; } return " + pName + "; }";

        WarningSummary renamed = runTypeCheck(renamedJs);
        if (!containsNormalized(renamed, expectedNorm)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:renamed-equivalent] semantic mismatch: expected warning="
                            + expectedNorm + " actualCount=" + renamed.count
                            + " warnings=" + join(renamed.descriptions));
