    private static WarningSummary runTypeCheck(String js) {
        Compiler compiler = new Compiler();
        com.google.javascript.rhino.Node root = compiler.parseTestCode(js);
        new ProcessClosurePrimitives(compiler, CheckLevel.ERROR, true).process(null, root);

